package game.world;
import java.util.*;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.test.context.*;
import org.springframework.test.annotation.DirtiesContext;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import static org.junit.jupiter.api.Assertions.*;

@SpringBootTest(webEnvironment=SpringBootTest.WebEnvironment.RANDOM_PORT)
@DirtiesContext(classMode=DirtiesContext.ClassMode.AFTER_CLASS)
@EnabledIfEnvironmentVariable(named="PHASE1_DATABASE_URL",matches="jdbc:postgresql://127\\.0\\.0\\.1:[0-9]+/qingyu_phase1_[a-z0-9_]+")
class NpcGuardIntegrationTest {
 @org.junit.jupiter.params.ParameterizedTest @org.junit.jupiter.params.provider.ValueSource(booleans={false,true}) void spearNpcSidestepsAtBoundaryToReachLegalAttackPosition(boolean threatened){synchronized(world){visitor();long now=System.currentTimeMillis();world.advanceNpcs(now);UUID guard=guards().getFirst(),monster=CharacterService.ISLAND_BEAST;var owner=characters.get(guard).hex();var cells=new ArrayList<SceneMap.Cell>();for(int q=-3;q<=3;q++)for(int r=-3;r<=3;r++)if(WeaponRules.distance(new WorldMap.Hex(0,0),new WorldMap.Hex(q,r))<=3)cells.add(new SceneMap.Cell(q,r,"grass",true));var scene=new SceneMap(UUID.randomUUID(),world.map().version(),1,2,owner,"edge-test",3,cells);tx().executeWithoutResult(s->scenes.save(scene));runtime.put(guard,scene.id(),new WorldMap.Hex(0,-2));characters.relocate(monster,owner.q(),owner.r());db.update("update characters set life='alive',hp=max_hp where id=?",monster);runtime.put(monster,scene.id(),new WorldMap.Hex(1,-3));db.update("update npc_tasks set task='pursue',target_id=? where actor_id=?",monster,guard);db.update("update characters set weapon=\'spear\',offhand=null where id=?",guard);assertTrue(WeaponRules.battlefieldCells(characters.weapon(guard),new WorldMap.Hex(0,-2),new WorldMap.Hex(1,-3),3).isEmpty());UUID battle=world.startBattle(guard,monster,world.map().version());if(threatened){db.update("update characters set weapon=null where id=?",monster);db.update("update battle_encounters set turn_account_id=?,turn_points=6 where id=?",monster,battle);tx().executeWithoutResult(s->battles.attackCell(monster,0,-2,Set.of(),now));}db.update("update battle_encounters set turn_account_id=?,turn_points=6 where id=?",guard,battle);assertTrue(relations.enemy(guard,monster));tx().executeWithoutResult(s->battles.advance(Set.of(),System.currentTimeMillis()+1000));assertTrue(db.queryForObject("select count(*) from battle_events where encounter_id=? and actor_id=? and kind='move'",Integer.class,battle,guard)>0,()->"A spear NPC must sidestep: "+db.queryForList("select kind,actor_id,q,r from battle_events where encounter_id=?",battle)+" task="+db.queryForList("select task from npc_tasks where actor_id=?",guard));}}
 @Test void deadAssigneeCannotReserveCorpse(){synchronized(world){UUID target=visitor();long now=System.currentTimeMillis();world.advanceNpcs(now);var guards=guards();UUID dead=guards.get(0),survivor=guards.get(1);db.update("insert into crimes(actor,faction_id,reason,created_at) values(?,'qingyu','test',?)",target,now);long alarm=db.queryForObject("insert into guard_alarms(faction_id,target_id,created_at) values('qingyu',?,?) returning id",Long.class,target,now);tx().executeWithoutResult(s->{characters.die(target,now);characters.die(dead,now);});UUID corpse=db.queryForObject("select id from loot_containers where source_id=? order by created_at desc limit 1",UUID.class,target);db.update("update npc_tasks set alarm_id=?,target_id=?,task='pursue',corpse_id=case when actor_id=? then ? else null end where actor_id in (?,?)",alarm,target,dead,corpse,dead,survivor);world.advanceNpcs(now+1000);assertNull(db.queryForObject("select corpse_id from npc_tasks where actor_id=?",UUID.class,dead));assertEquals(corpse,db.queryForObject("select corpse_id from npc_tasks where actor_id=?",UUID.class,survivor));}}
 @Test void blockedHomeWaitsNearbyThenReturnsWithoutChangingHome(){synchronized(world){UUID blocker=visitor();long now=System.currentTimeMillis();world.advanceNpcs(now);UUID guard=guards().getFirst();var home=runtime.position(guard);var far=runtime.map(home.sceneId()).cells().stream().filter(c->c.walkable()&&WeaponRules.distance(c.hex(),home.hex())>5&&!runtime.occupied(home.sceneId(),guard).contains(c.hex())).findFirst().orElseThrow();runtime.put(guard,home.sceneId(),far.hex());runtime.put(blocker,home.sceneId(),home.hex());db.update("update npc_tasks set task='return',next_think=0 where actor_id=?",guard);for(int i=0;i<100;i++){world.advanceNpcs(now+1000L*(i+1));world.stepNpcRoutes();}var near=runtime.position(guard);assertTrue(WeaponRules.distance(near.hex(),home.hex())<=2);assertNotEquals(home.hex(),near.hex());assertEquals("return",db.queryForObject("select task from npc_tasks where actor_id=?",String.class,guard));runtime.leave(blocker);for(int i=0;i<10;i++){world.advanceNpcs(now+101000L+1000L*i);world.stepNpcRoutes();}assertEquals(home.hex(),runtime.position(guard).hex());assertEquals("idle",db.queryForObject("select task from npc_tasks where actor_id=?",String.class,guard));}}
 @Test void unassignedGuardHoldsPostDuringDistantCombat(){synchronized(world){UUID player=visitor();long now=System.currentTimeMillis();world.advanceNpcs(now);UUID guard=guards().getFirst(),monster=CharacterService.ISLAND_BEAST;var p=runtime.position(guard);for(var r:runtime.residents(p.sceneId()))if(!r.characterId().equals(guard))runtime.leave(r.characterId());characters.relocate(monster,characters.get(guard).q(),characters.get(guard).r());db.update("update characters set life='alive',hp=max_hp where id=?",monster);var far=runtime.map(p.sceneId()).cells().stream().filter(c->c.walkable()&&WeaponRules.distance(p.hex(),c.hex())>5).findFirst().orElseThrow();runtime.put(monster,p.sceneId(),far.hex());UUID battle=world.startBattle(guard,monster,world.map().version());db.update("update battle_encounters set turn_account_id=?,turn_points=6 where id=?",guard,battle);var before=db.queryForMap("select q,r from battle_actors where encounter_id=? and account_id=?",battle,guard);tx().executeWithoutResult(s->battles.advance(Set.of(),now+100));assertEquals(before,db.queryForMap("select q,r from battle_actors where encounter_id=? and account_id=?",battle,guard));}}
 @Test void playerCanInitiateAgainstNeutralServiceBeforeFirstAttack(){synchronized(world){UUID player=visitor();UUID officer=(UUID)law.stations(player).getFirst().get("officer_id");long now=System.currentTimeMillis();UUID battle=world.startBattle(player,officer,world.map().version());db.update("update battle_encounters set turn_account_id=? where id=?",player,battle);tx().executeWithoutResult(s->battles.advance(Set.of(player),now+1));assertTrue(battles.engaged(player));assertFalse(law.wanted(player,"qingyu"));}}
 @Autowired NpcNavigation navigation;@Autowired NpcPerception perception;@Autowired TownService towns;
 @Test void indoorKnowledgeHidesExactCellAndDoorIsActuallyRequired(){synchronized(world){UUID viewer=visitor(),target=visitor();world.advanceNpcs(System.currentTimeMillis());var outdoor=runtime.position(target);var door=towns.doors(outdoor.sceneId()).getFirst();runtime.put(target,outdoor.sceneId(),door.cell());world.useDoor(target,door.id(),world.map().version());var seen=perception.observe(viewer,target,world.map(),false);assertNotNull(seen);assertFalse(seen.precise());assertEquals(door.cell(),seen.hex());assertEquals(outdoor.sceneId(),seen.sceneId());var guard=guards().getFirst();assertTrue(perception.observe(guard,target,world.map(),true).precise());assertThrows(RuntimeException.class,()->world.useDoor(viewer,door.id(),world.map().version()));var p=runtime.position(target);assertNotNull(navigation.route(viewer,p.sceneId(),p.hex(),1,world.map(),true));}}
 @Test void carriedCorpsesFallToGroundWhenNpcDies(){synchronized(world){UUID target=visitor();long now=System.currentTimeMillis();world.advanceNpcs(now);UUID guard=guards().getFirst();var location=runtime.position(target);tx().executeWithoutResult(s->characters.die(target,now));UUID corpse=db.queryForObject("select id from loot_containers where source_id=? order by created_at desc limit 1",UUID.class,target);runtime.put(guard,location.sceneId(),location.hex());world.lootCommand(guard,new LootService.Command("carry",corpse,null,null,world.map().version(),null,null));assertEquals(guard,db.queryForObject("select carrier_id from loot_containers where id=?",UUID.class,corpse));tx().executeWithoutResult(s->characters.die(guard,now+1));assertNull(db.queryForObject("select carrier_id from loot_containers where id=?",UUID.class,corpse));assertEquals(location.sceneId(),db.queryForObject("select scene_id from loot_containers where id=?",UUID.class,corpse));}}
 @Test void firstAlarmKeepsAssignmentAndLaterAlarmUsesOnlySpareGuard(){synchronized(world){UUID first=visitor(),later=visitor();long now=System.currentTimeMillis();world.advanceNpcs(now);db.update("insert into guard_alarms(faction_id,target_id,created_at) values('qingyu',?,?),('qingyu',?,?)",first,now,later,now+1);for(UUID id:List.of(first,later))db.update("insert into crimes(actor,faction_id,reason,created_at) values(?,'qingyu','test',?)",id,now);world.advanceNpcs(now+1000);assertEquals(1,db.queryForObject("select count(*) from npc_tasks where target_id=?",Integer.class,first));assertEquals(1,db.queryForObject("select count(*) from npc_tasks where target_id=?",Integer.class,later));assertEquals(1,db.queryForObject("select count(*) from npc_tasks where post_id is not null and task='idle'",Integer.class));}}
 @Test void guardAndMonsterUseSharedBattleWithoutPlayerTarget(){synchronized(world){visitor();long now=System.currentTimeMillis();world.advanceNpcs(now);UUID guard=guards().getFirst(),monster=CharacterService.ISLAND_BEAST;var p=runtime.position(guard);for(var r:runtime.residents(p.sceneId()))if(!r.characterId().equals(guard))runtime.leave(r.characterId());characters.relocate(monster,characters.get(guard).q(),characters.get(guard).r());db.update("update characters set life='alive',hp=max_hp where id=?",monster);var next=p.hex().neighbors().stream().filter(h->runtime.map(p.sceneId()).cells().stream().anyMatch(c->c.walkable()&&c.hex().equals(h))).findFirst().orElseThrow();runtime.put(monster,p.sceneId(),next);UUID battle=world.startBattle(guard,monster,world.map().version());db.update("update battle_encounters set turn_account_id=?,turn_points=6 where id=?",guard,battle);tx().executeWithoutResult(s->battles.advance(Set.of(),now+100));assertTrue(battles.engaged(guard));assertTrue(db.queryForObject("select turn_points from battle_encounters where id=?",Integer.class,battle)<6);assertEquals(0,db.queryForObject("select count(*) from crimes where actor=?",Integer.class,guard));}}
 @DynamicPropertySource static void config(DynamicPropertyRegistry r){r.add("spring.datasource.url",()->System.getenv("PHASE1_DATABASE_URL"));r.add("spring.datasource.username",()->"worldgame");r.add("spring.datasource.password",()->"local-only");r.add("app.admin-password",()->"phase-one-local-test-only");}
 @Autowired WorldService world;@Autowired AccountService accounts;@Autowired CharacterService characters;@Autowired SceneRuntime runtime;@Autowired SceneService scenes;@Autowired LawService law;@Autowired BattleService battles;@Autowired NpcRelations relations;@Autowired JdbcTemplate db;@Autowired PlatformTransactionManager manager;
 TransactionTemplate tx(){return new TransactionTemplate(manager);}
 @BeforeEach void reset(){synchronized(world){db.update("delete from handovers");db.update("delete from crimes");db.update("delete from production_tasks");db.update("delete from guard_alarms");db.update("delete from loot_containers");battles.reset();db.update("delete from scene_portals");db.update("delete from scene_documents");scenes.refresh();db.update("update characters set life='dead',timer_end=? where kind='monster'",Long.MAX_VALUE);db.update("update characters set next_move=? where kind<>'player'",Long.MAX_VALUE);}}
 UUID visitor(){var a=accounts.register("guard"+UUID.randomUUID().toString().substring(0,10),"local-test-password",world.map().spawn());db.update("update accounts set approved=true,entered=true where id=?",a.id());characters.ensurePlayers();var h=world.map().tiles().stream().filter(t->t.place()!=null&&t.place().type().equals("town")).findFirst().orElseThrow().hex();characters.relocate(a.id(),h.q(),h.r());world.enterScene(a.id(),world.map().version());return a.id();}
 List<UUID> guards(){return db.queryForList("select actor_id from npc_tasks where post_id is not null order by actor_id",UUID.class);}
 @Test void postsHaveRealGuardsAndRespectReserve(){synchronized(world){UUID target=visitor();long now=System.currentTimeMillis();world.advanceNpcs(now);assertEquals(3,guards().size());db.update("insert into crimes(actor,faction_id,reason,created_at) values(?,'qingyu','test',?)",target,now);world.advanceNpcs(now+1000);assertEquals(1,db.queryForObject("select count(*) from npc_tasks where task='pursue'",Integer.class));world.advanceNpcs(now+2000);assertTrue(db.queryForObject("select count(*) from npc_tasks where task='idle' and post_id is not null",Integer.class)>=1);}}
 @Test void friendlyPlayersAreNotGuardTargetsButMaliciousNpcsAre(){synchronized(world){UUID player=visitor();world.advanceNpcs(System.currentTimeMillis());UUID guard=guards().getFirst();db.update("update characters set life='alive',hp=max_hp where id=?",CharacterService.ISLAND_BEAST);assertFalse(relations.enemy(guard,player));assertTrue(relations.enemy(guard,CharacterService.ISLAND_BEAST));assertTrue(relations.enemy(CharacterService.ISLAND_BEAST,guard));}}
 @Test void deathDoesNotAwardAndGuardMustActuallyCarryAndSubmit(){synchronized(world){UUID target=visitor();long now=System.currentTimeMillis();world.advanceNpcs(now);UUID guard=guards().getFirst();db.update("insert into crimes(actor,faction_id,reason,created_at) values(?,'qingyu','test',?)",target,now);tx().executeWithoutResult(s->characters.die(target,now));assertTrue(law.wanted(target,"qingyu"));assertEquals(0,db.queryForObject("select coalesce(sum(quantity),0) from inventories where character_id=? and item_code='silver_coin'",Long.class,guard));var corpse=db.queryForMap("select id,scene_id,battle_q,battle_r from loot_containers where source_id=? order by created_at desc limit 1",target);runtime.put(guard,(UUID)corpse.get("scene_id"),new WorldMap.Hex(((Number)corpse.get("battle_q")).intValue(),((Number)corpse.get("battle_r")).intValue()));db.update("update npc_tasks set task='collect',target_id=?,corpse_id=?,next_think=0 where actor_id=?",target,corpse.get("id"),guard);for(int i=0;i<160&&law.wanted(target,"qingyu");i++){world.advanceNpcs(now+1000L*(i+1));world.stepNpcRoutes();}assertFalse(law.wanted(target,"qingyu"),()->db.queryForList("select task,failures,corpse_id,last_scene,home_scene from npc_tasks where actor_id=?",guard)+" "+db.queryForList("select life,timer_kind,hp from characters where id=?",guard)+" "+db.queryForList("select carrier_id,battle_id from loot_containers where source_id=?",target));assertEquals(1,db.queryForObject("select quantity from inventories where character_id=? and item_code='silver_coin'",Long.class,guard));}}
}
